// The port against its reference: for every bundle in samples/ and
// test/fixtures/, summarize() must produce exactly what Provbana's Python
// summariser produced (test/golden/, regenerated by tools/golden.py).

import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { test } from "node:test";

import { detectDocumentType, summarize } from "../src/summarize.js";
import { parseJson } from "../src/datatypes.js";

const root = new URL("..", import.meta.url);
const read = (path) => readFileSync(new URL(path, root), "utf8");

for (const folder of ["samples", "test/fixtures"]) {
  for (const name of readdirSync(new URL(folder, root)).filter((f) => f.endsWith(".json"))) {
    test(`${folder}/${name} matches Provbana's summary`, () => {
      const golden = JSON.parse(read(`test/golden/${name}`));
      const bundle = parseJson(read(`${folder}/${name}`));
      const summary = JSON.parse(JSON.stringify(summarize(bundle, { today: golden.today })));
      assert.deepStrictEqual(summary, golden.summary);
      // the order the gaps are listed in is part of the output
      assert.deepStrictEqual(Object.keys(summary.quality.gaps),
        Object.keys(golden.summary.quality.gaps));
      assert.equal(detectDocumentType(bundle).id, golden.doc_type);
    });
  }
}
